@page "/settings"
@rendermode InteractiveServer
@using sv_54affb9681ba4f79af9d40852ac0e32f.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h5 class="sidebar-heading">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Icon</span>
                    <span>@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center p-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastMessage is not null)
        {
            <div class="toast-notification @(_toastFading ? "fade-out" : "")">
                <span class="toast-icon">✓</span> @_toastMessage
            </div>
        }

        @if (_showRevokeDialog)
        {
            <div class="dialog-overlay" @onclick="() => _showRevokeDialog = false">
                <div class="dialog-box" @onclick:stopPropagation="true">
                    <h5>Revoke Session</h5>
                    <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                    <div class="d-flex gap-2 justify-content-end">
                        <button class="btn btn-secondary btn-sm" @onclick="() => _showRevokeDialog = false">Cancel</button>
                        <button class="btn btn-danger btn-sm" @onclick="ConfirmRevokeSession">Revoke</button>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    private record SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string? _toastMessage;
    private bool _toastFading;
    private CancellationTokenSource? _toastCts;

    // Profile state
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    // Notifications state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = [];
    private HashSet<string> _mutedChannels = [];

    // Security state
    private SecuritySettings? _security;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _showRevokeDialog;
    private string? _revokeSessionId;

    // Appearance state
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] AvailableLanguages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        var profile = profileTask.Result;
        _savedProfile = profile;
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _avatarUrl = profile.AvatarUrl;

        var notif = notifTask.Result;
        _emailNotifications = notif.EmailNotifications;
        _pushNotifications = notif.PushNotifications;
        _weeklyDigest = notif.WeeklyDigest;
        _allChannels = new List<string>(notif.MutedChannels.Concat(new[] { "general", "engineering", "design" }).Distinct());
        _mutedChannels = new HashSet<string>(notif.MutedChannels);

        _security = securityTask.Result;

        var appearance = appearanceTask.Result;
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    // ── Toast helper ────────────────────────────────────────────────
    private async Task ShowToast(string message)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastFading = false;
        StateHasChanged();

        try
        {
            await Task.Delay(2500, token);
            _toastFading = true;
            StateHasChanged();
            await Task.Delay(500, token);
        }
        catch (TaskCanceledException) { }
        finally
        {
            if (!token.IsCancellationRequested)
            {
                _toastMessage = null;
                _toastFading = false;
                StateHasChanged();
            }
        }
    }

    // ── Profile ─────────────────────────────────────────────────────
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section>
            <h3 class="section-title">Profile</h3>

            <div class="avatar-area mb-4">
                <img src="@_avatarUrl" alt="Avatar" class="avatar-preview" />
                <div class="mt-2">
                    <label class="form-label fw-semibold">Avatar URL</label>
                    <input type="url" class="form-control" @bind="_avatarUrl" />
                </div>
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Display Name</label>
                <input type="text" class="form-control" @bind="_displayName" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Email</label>
                <input type="email" class="form-control" @bind="_email" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Bio</label>
                <textarea class="form-control" rows="4" @bind="_bio"></textarea>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is null) return;
        _displayName = _savedProfile.DisplayName;
        _email = _savedProfile.Email;
        _bio = _savedProfile.Bio;
        _avatarUrl = _savedProfile.AvatarUrl;
    }

    // ── Notifications ───────────────────────────────────────────────
    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section>
            <h3 class="section-title">Notifications</h3>

            <div class="toggle-row">
                <label>Email Notifications</label>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" @bind="_emailNotifications" />
                </div>
            </div>

            <div class="toggle-row">
                <label>Push Notifications</label>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" @bind="_pushNotifications" />
                </div>
            </div>

            <div class="toggle-row">
                <label>Weekly Digest</label>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" @bind="_weeklyDigest" />
                </div>
            </div>

            <h5 class="mt-4 mb-3">Muted Channels</h5>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var ch = channel;
                    <div class="form-check">
                        <input class="form-check-input darker-border-checkbox" type="checkbox" id="@($"ch-{ch}")"
                               checked="@_mutedChannels.Contains(ch)"
                               @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                        <label class="form-check-label" for="@($"ch-{ch}")">
                            #@ch
                        </label>
                    </div>
                }
            </div>

            <button class="btn btn-primary mt-4" @onclick="SaveNotifications">Save Preferences</button>
        </section>
    };

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted) _mutedChannels.Add(channel);
        else _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // ── Security ────────────────────────────────────────────────────
    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section>
            <h3 class="section-title">Security</h3>

            <!-- Change Password -->
            <div class="expandable-panel mb-4">
                <div class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>🔑 Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
                </div>
                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        @if (_passwordError is not null)
                        {
                            <div class="alert alert-danger py-2">@_passwordError</div>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <!-- 2FA -->
            <div class="toggle-row mb-4">
                <div>
                    <label class="fw-semibold">Two-Factor Authentication</label>
                    <div class="status-badge @(_security!.TwoFactorEnabled ? "status-on" : "status-off")">
                        @(_security.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </div>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch"
                           checked="@_security.TwoFactorEnabled" disabled />
                </div>
            </div>

            @if (_security.LastPasswordChange is not null)
            {
                <p class="text-muted small">Last password change: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <!-- Active Sessions -->
            <h5 class="mt-4 mb-3">Active Sessions</h5>
            <div class="table-responsive">
                <table class="table table-hover align-middle">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @for (var i = 0; i < _security.Sessions.Count; i++)
                        {
                            var session = _security.Sessions[i];
                            var isCurrent = i == 0;
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrent)
                                    {
                                        <span class="badge bg-success ms-2">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (!isCurrent)
                                    {
                                        <button class="btn btn-outline-danger btn-sm"
                                                @onclick="() => PromptRevokeSession(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </section>
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task UpdatePassword()
    {
        _passwordError = null;
        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "All password fields are required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New passwords do not match.";
            return;
        }
        if (_newPassword.Length < 8)
        {
            _passwordError = "Password must be at least 8 characters.";
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = _newPassword = _confirmPassword = "";
        _changePasswordExpanded = false;
        await ShowToast("Password updated successfully!");
    }

    private void PromptRevokeSession(string sessionId)
    {
        _revokeSessionId = sessionId;
        _showRevokeDialog = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_revokeSessionId is not null)
        {
            await SettingsService.RevokeSessionAsync(_revokeSessionId);
            _security = await SettingsService.GetSecuritySettingsAsync();
        }
        _showRevokeDialog = false;
        _revokeSessionId = null;
        await ShowToast("Session revoked.");
    }

    // ── Appearance ──────────────────────────────────────────────────
    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section>
            <h3 class="section-title">Appearance</h3>

            <!-- Theme -->
            <h5 class="mb-2">Theme</h5>
            <div class="d-flex gap-3 mb-4">
                @foreach (var t in new[] { "Light", "Dark", "System" })
                {
                    var theme = t;
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <!-- Font Size -->
            <h5 class="mb-2">Font Size</h5>
            <div class="d-flex gap-3 mb-4">
                @foreach (var fs in new[] { "Small", "Medium", "Large" })
                {
                    var size = fs;
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <!-- Language -->
            <div class="mb-4" style="max-width: 300px;">
                <h5 class="mb-2">Language</h5>
                <select class="form-select" @bind="_language">
                    @foreach (var lang in AvailableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="toggle-row mb-4">
                <label class="fw-semibold">Compact Mode</label>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" @bind="_compactMode" />
                </div>
            </div>

            <!-- Live Preview -->
            <h5 class="mb-2">Preview</h5>
            <div class="preview-area @GetPreviewClasses()">
                <h6>Sample Heading</h6>
                <p>This is a preview of your selected appearance settings. The background, font size, and spacing reflect your choices.</p>
                <button class="btn btn-sm @(_theme == "Dark" ? "btn-light" : "btn-primary")">Sample Button</button>
            </div>

            <button class="btn btn-primary mt-4" @onclick="SaveAppearance">Save</button>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_theme switch
        {
            "Dark" => "preview-dark",
            "System" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_fontSize switch
        {
            "Small" => "preview-font-sm",
            "Large" => "preview-font-lg",
            _ => "preview-font-md"
        });
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(' ', classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }
}

